?- self(Self),
   Self ! goodbye(bob),
   receive({
       hello(Name) ->
           format("Hello, ~w!~n", [Name]) ;
       goodbye(Name) ->
           format("Goodbye, ~w!~n", [Name])
   }).

?- self(Self),
   Self ! number(-2),
   receive({
       number(N) if N > 0 ->
           format("Positive number: ~p~n", [N]) ;
       number(N) if N =< 0 ->
           format("Non-positive number: ~p~n", [N])
   }).

?- receive({
       person(Name) ->
           format("Hello, ~w!~n", [Name])
   }, [
       timeout(1),
       on_timeout(writeln('No person arrived.'))
   ]).
